	// the value of tickers is either a dict or a list
	//
	// dict
	//
	//     {
	//         'marketId1': { ... },
	//         'marketId2': { ... },
	//         ...
	//     }
	//
	// list
	//
	//     [
	//         { 'market': 'marketId1', ... },
	//         { 'market': 'marketId2', ... },
	//         ...
	//     ]
	//
	symbols := GetArg(optionalArgs, 0, nil)
	_ = symbols
	params := GetArg(optionalArgs, 1, map[string]any{})
